// Source fixtures: circuitpython-source/src/apps/Orion/modules/latch.py and pick.py with
// core/note_array.py. Traces live in fixtures/t09h_source_traces.inc, generated by
// fixtures/t09h/gen_traces.py under python -I (run from the repository root).
// Trace functions named trace_dev_* carry the documented release-safety deviations (latch_pick.cpp);
// each such step checks the C++ result and that the source (python -I) result differs.
#include "modules/generated/module_counts_generated.hpp"
#include "modules/common/registry.hpp"
#include "modules/core/latch/latch_pick.hpp"
#include <cassert>
#include <cstdio>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <initializer_list>

namespace {
using namespace orbit;

struct Pair {
  std::uint8_t pitch;
  std::uint8_t velocity;
};

std::uint32_t g_random_draws = 0;
std::uint32_t next_counter(void* ctx) { return ++*static_cast<std::uint32_t*>(ctx); }

bool equal(const char* a, const char* b) { return std::strcmp(a, b) == 0; }

// Replays one module through its descriptor, the same way the chain calls it.
struct Run {
  explicit Run(const ModuleDescriptor& descriptor) : d(descriptor) { d.construct(state); }
  ~Run() { d.destroy(state); }
  Run(const Run&) = delete;
  Run& operator=(const Run&) = delete;

  void set_int(std::uint8_t index, std::int32_t value) {
    std::uint8_t effects = 0;
    assert(d.set_param(state, index, ParamValue::integer(value), global, effects));
    assert(effects == 0);
  }
  void set_bool(std::uint8_t index, bool value) {
    std::uint8_t effects = 0;
    assert(d.set_param(state, index, ParamValue::boolean(value), global, effects));
    assert(effects == 0);
  }
  void stop() { d.reset(state, ResetReason::Stop); }

  NoteBatch process(std::initializer_list<Pair> on, std::initializer_list<std::uint8_t> off,
                    std::uint8_t channel = 0) {
    NoteBatch input{}, output{};
    for (const auto& p : on) assert(input.on.append({p.pitch, p.velocity, channel}) == PushResult::Added);
    for (const auto p : off) assert(input.off.append({p, 0, channel}) == PushResult::Added);
    TransportView view{};
    ProcessContext context{TimeSample{0, 0}, global, view, random};
    d.process(state, context, input, output);
    assert(!output.overflowed());
    assert(output.on.count <= kPolyphony && output.off.count <= kPolyphony);
    return output;
  }

  void step(std::initializer_list<Pair> on, std::initializer_list<std::uint8_t> off, std::initializer_list<Pair> expected_on,
            std::initializer_list<std::uint8_t> expected_off) {
    const auto output = process(on, off);
    if (!matches(output, expected_on, expected_off)) {
      std::fprintf(stderr, "MISMATCH out_on=%u out_off=%u\n", static_cast<unsigned>(output.on.count),
                   static_cast<unsigned>(output.off.count));
      for (std::uint16_t i = 0; i < output.on.count; ++i) std::fprintf(stderr, " on %u/%u", output.on.items[i].pitch, output.on.items[i].velocity);
      for (std::uint16_t i = 0; i < output.off.count; ++i) std::fprintf(stderr, " off %u", output.off.items[i].pitch);
      std::fprintf(stderr, "\n");
    }
    assert(matches(output, expected_on, expected_off));
  }

  // A documented deviation: the C++ result must match cpp_*, and the source result must not.
  void step_dev(std::initializer_list<Pair> on, std::initializer_list<std::uint8_t> off,
                std::initializer_list<Pair> source_on, std::initializer_list<std::uint8_t> source_off,
                std::initializer_list<Pair> cpp_on, std::initializer_list<std::uint8_t> cpp_off) {
    const auto output = process(on, off);
    assert(matches(output, cpp_on, cpp_off));
    assert(!matches(output, source_on, source_off));
  }

  static bool matches(const NoteBatch& output, std::initializer_list<Pair> on, std::initializer_list<std::uint8_t> off) {
    if (static_cast<std::size_t>(output.on.count) != on.size()) return false;
    if (static_cast<std::size_t>(output.off.count) != off.size()) return false;
    std::size_t i = 0;
    for (const auto& p : on) {
      if (output.on.items[i].pitch != p.pitch || output.on.items[i].velocity != p.velocity) return false;
      ++i;
    }
    i = 0;
    for (const auto p : off) {
      if (output.off.items[i++].pitch != p) return false;
    }
    return true;
  }

  const ModuleDescriptor& d;
  ModuleState state{};
  GlobalState global{};
  RandomSource random{&g_random_draws, next_counter};
};

#include "fixtures/t09h_source_traces.inc"

const LatchModuleState& latch_state(const Run& r) { return r.state.storage.latch; }
const PickModuleState& pick_state(const Run& r) { return r.state.storage.pick; }

// Per-pitch balance: emitted note-ons minus emitted note-offs equals the number of entries the module
// still holds for that pitch. Latch holds each pitch at most once; pick may hold duplicates.
struct Ledger {
  std::int32_t on[128]{};
  std::int32_t off[128]{};
  void add(const NoteBatch& output) {
    for (std::uint16_t i = 0; i < output.on.count; ++i) ++on[output.on.items[i].pitch];
    for (std::uint16_t i = 0; i < output.off.count; ++i) ++off[output.off.items[i].pitch];
  }
  std::int32_t sounding(std::uint8_t pitch) const { return on[pitch] - off[pitch]; }
};

struct Lcg {
  std::uint32_t s;
  std::uint32_t next() { s = s * 1664525U + 1013904223U; return s >> 8; }
  std::uint32_t range(std::uint32_t n) { return next() % n; }
};

void test_descriptor() {
  const auto* latch = find_module("latch");
  const auto* pick = find_module("pick");
  assert(latch && latch == &latch_module_descriptor() && pick && pick == &pick_module_descriptor());
  assert(!find_module("phraser"));
  assert(module_count() == orbit::kGeneratedProcessorCount && module_at(10) == latch && module_at(11) == pick);

  // latch.py: POLY=12, range 1..12, persisted name polyphony.
  assert(latch->version == 1 && latch->param_count == 1);
  assert(equal(latch->params[0].name, "polyphony") && equal(latch->params[0].display_label, "POLY"));
  assert(latch->params[0].default_value.value.integer == 12);
  assert(latch->params[0].minimum.value.integer == 1 && latch->params[0].maximum.value.integer == 12);

  // pick.py: parameter names, order, labels, defaults and ranges.
  assert(pick->version == 1 && pick->param_count == 5);
  assert(equal(pick->params[0].name, "pick_mode") && equal(pick->params[0].display_label, "MDE"));
  assert(pick->params[0].option_count == 4 && equal(pick->params[0].options[0], "STRT") &&
         equal(pick->params[0].options[1], "END") && equal(pick->params[0].options[2], "LOW") &&
         equal(pick->params[0].options[3], "HIGH"));
  assert(pick->params[0].maximum.value.integer == 3);
  assert(equal(pick->params[1].name, "count") && equal(pick->params[1].display_label, "COUNT"));
  assert(pick->params[1].default_value.value.integer == 1 && pick->params[1].minimum.value.integer == 1 &&
         pick->params[1].maximum.value.integer == 12);
  assert(equal(pick->params[2].name, "invert") && equal(pick->params[2].display_label, "INV"));
  assert(pick->params[2].type == ParamType::Boolean && pick->params[2].default_value.value.boolean == false);
  assert(equal(pick->params[3].name, "offset") && equal(pick->params[3].display_label, "OFST"));
  assert(pick->params[3].default_value.value.integer == 0 && pick->params[3].maximum.value.integer == 12);
  assert(equal(pick->params[4].name, "octaves") && equal(pick->params[4].display_label, "OCT"));
  assert(pick->params[4].default_value.value.integer == 0);

  // Out-of-range and wrong-typed values are rejected without mutation.
  Run l(latch_module_descriptor());
  std::uint8_t effects = 0;
  assert(!latch->set_param(l.state, 0, ParamValue::integer(0), l.global, effects));
  assert(!latch->set_param(l.state, 0, ParamValue::integer(13), l.global, effects));
  assert(!latch->set_param(l.state, 0, ParamValue::decimal(4.0f), l.global, effects));
  assert(!latch->set_param(l.state, 1, ParamValue::integer(4), l.global, effects));
  assert(latch_state(l).polyphony == 12 && effects == 0);

  Run p(pick_module_descriptor());
  assert(!pick->set_param(p.state, 0, ParamValue::integer(4), p.global, effects));
  assert(!pick->set_param(p.state, 1, ParamValue::integer(0), p.global, effects));
  assert(!pick->set_param(p.state, 1, ParamValue::integer(13), p.global, effects));
  assert(!pick->set_param(p.state, 2, ParamValue::integer(1), p.global, effects));
  assert(!pick->set_param(p.state, 3, ParamValue::integer(13), p.global, effects));
  assert(!pick->set_param(p.state, 5, ParamValue::integer(0), p.global, effects));
  assert(pick_state(p).pick_mode == 0 && pick_state(p).count == 1 && !pick_state(p).invert && pick_state(p).offset == 0);
  assert(effects == 0);
}

// Latch releases must use the channel of the note they end, and a toggle matches by pitch.
void test_latch_channel_and_matching() {
  Run r(latch_module_descriptor());
  auto out = r.process({{60, 100}}, {}, 3);
  assert(out.on.count == 1 && out.on.items[0].channel == 3 && out.on.items[0].velocity == 100);
  out = r.process({{60, 40}}, {}, 5);  // Same pitch on another channel toggles the latched note off.
  assert(out.on.count == 0 && out.off.count == 1 && out.off.items[0].pitch == 60);
  assert(out.off.items[0].channel == 3);
  assert(latch_state(r).held.count == 0);
}

// Latch: incoming note-offs never unlatch; POLY caps holds and evicts oldest first.
void test_latch_capacity_and_reset() {
  Run r(latch_module_descriptor());
  for (std::uint8_t p = 60; p < 72; ++p) r.step({{p, 90}}, {}, {{p, 90}}, {});
  assert(latch_state(r).held.count == 12 && latch_state(r).held_overflow == 0);
  r.step({{72, 90}}, {}, {{72, 90}}, {60});
  assert(latch_state(r).held.count == 12 && latch_state(r).held.items[0].pitch == 61);

  // ParameterChange keeps latched notes (the source does not stop the module on a parameter edit).
  r.d.reset(r.state, ResetReason::ParameterChange);
  assert(latch_state(r).held.count == 12);
  r.stop();
  assert(latch_state(r).held.count == 0 && latch_state(r).output_overflow == 0);
  // Stop is silent: nothing is released by the module; the controller releases sounding notes.
  const auto after = r.process({}, {});
  assert(after.on.count == 0 && after.off.count == 0);
}

// Pick: stop clears held and selected notes; the module emits no releases on stop.
void test_pick_reset_and_capacity() {
  Run r(pick_module_descriptor());
  r.set_int(1, 2);
  r.step({{60, 100}, {64, 90}}, {}, {{60, 100}, {64, 90}}, {});
  r.d.reset(r.state, ResetReason::ParameterChange);
  assert(pick_state(r).held.count == 2 && pick_state(r).active.count == 2);
  r.stop();
  assert(pick_state(r).held.count == 0 && pick_state(r).active.count == 0);
  r.step({}, {}, {}, {});

  // Thirteen holds: the thirteenth is counted and not selected or sent.
  Run c(pick_module_descriptor());
  c.set_int(1, 12);
  c.set_int(0, 3);
  c.step({{60, 90}, {61, 90}, {62, 90}, {63, 90}, {64, 90}, {65, 90}, {66, 90}, {67, 90}, {68, 90}, {69, 90},
          {70, 90}, {71, 90}}, {}, {{71, 90}, {70, 90}, {69, 90}, {68, 90}, {67, 90}, {66, 90}, {65, 90}, {64, 90}, {63, 90},
          {62, 90}, {61, 90}, {60, 90}}, {});
  c.step({{72, 100}}, {}, {}, {});
  assert(pick_state(c).held.count == 12 && pick_state(c).held_overflow == 1);
}

// Pick: a selected note whose OCT-shifted pitch leaves MIDI 0..127 is not selected (deviation 3).
// The source emits 132 for 60 with OCT=6 (its trace is dev_pick_octave_out_of_midi) and raises
// ValueError for a negative result; the C++ module skips both and counts them.
void test_pick_octave_range() {
  Run high(pick_module_descriptor());
  high.set_int(4, 6);
  high.step({{100, 90}}, {}, {}, {});  // 100 + 72 = 172.
  assert(pick_state(high).range_skipped == 1 && pick_state(high).active.count == 0);

  Run low(pick_module_descriptor());
  low.set_int(4, -6);
  low.step({{60, 90}}, {}, {}, {});  // 60 - 72 is negative.
  assert(pick_state(low).range_skipped == 1 && pick_state(low).active.count == 0);

  Run edge(pick_module_descriptor());
  edge.set_int(4, 0);
  edge.step({{127, 90}}, {}, {{127, 90}}, {});  // The top of the MIDI range is valid.
  assert(pick_state(edge).range_skipped == 0);
}

// Randomized latch invariants: per pitch, emitted on minus off is 1 exactly while the note is latched.
void test_latch_fuzz_balance() {
  for (std::uint32_t seed = 1; seed <= 32; ++seed) {
    Lcg rng{seed * 2654435U + 11U};
    Run r(latch_module_descriptor());
    r.set_int(0, static_cast<std::int32_t>(1 + rng.range(12)));
    Ledger ledger;
    for (int step = 0; step < 600; ++step) {
      if (rng.range(60) == 0) r.set_int(0, static_cast<std::int32_t>(1 + rng.range(12)));
      if (rng.range(80) == 0) {
        r.stop();
        for (std::size_t pitch = 0; pitch < 128; ++pitch) {
          // Stop is silent in the module; the controller sends all-notes-off, modelled here.
          ledger.on[pitch] = 0;
          ledger.off[pitch] = 0;
        }
        continue;
      }
      Pair ons[4]{};
      std::uint8_t offs[3]{};
      const auto on_count = rng.range(4);
      const auto off_count = rng.range(3);
      for (std::uint32_t k = 0; k < on_count; ++k) ons[k] = {static_cast<std::uint8_t>(56 + rng.range(10)), static_cast<std::uint8_t>(1 + rng.range(127))};
      for (std::uint32_t k = 0; k < off_count; ++k) offs[k] = static_cast<std::uint8_t>(56 + rng.range(10));
      NoteBatch input{}, output{};
      for (std::uint32_t k = 0; k < on_count; ++k) assert(input.on.append({ons[k].pitch, ons[k].velocity, 0}) == PushResult::Added);
      for (std::uint32_t k = 0; k < off_count; ++k) assert(input.off.append({offs[k], 0, 0}) == PushResult::Added);
      TransportView view{};
      ProcessContext context{TimeSample{0, 0}, r.global, view, r.random};
      r.d.process(r.state, context, input, output);
      assert(!output.overflowed());
      ledger.add(output);
      assert(latch_state(r).held.count <= kPolyphony);
      assert(latch_state(r).output_overflow == 0 && latch_state(r).held_overflow == 0);
      // Balance: each pitch sounds exactly when the module latches it.
      for (std::uint8_t pitch = 56; pitch < 66; ++pitch) {
        bool latched = false;
        for (std::uint16_t i = 0; i < latch_state(r).held.count; ++i) latched = latched || latch_state(r).held.items[i].pitch == pitch;
        assert(ledger.sounding(pitch) == (latched ? 1 : 0));
      }
    }
  }
}

// Randomized pick invariants: per pitch, emitted on minus off equals the selected entries with that pitch;
// selections never exceed COUNT or the held list.
void test_pick_fuzz_balance() {
  for (std::uint32_t seed = 1; seed <= 32; ++seed) {
    Lcg rng{seed * 40503U + 7U};
    Run r(pick_module_descriptor());
    r.set_int(0, static_cast<std::int32_t>(rng.range(4)));
    r.set_int(1, static_cast<std::int32_t>(1 + rng.range(12)));
    r.set_bool(2, rng.range(2) == 1);
    r.set_int(3, static_cast<std::int32_t>(rng.range(13)));
    r.set_int(4, static_cast<std::int32_t>(rng.range(5)) - 2);
    Ledger ledger;
    for (int step = 0; step < 600; ++step) {
      const auto roll = rng.range(100);
      if (roll < 3) {
        r.stop();
        for (std::size_t pitch = 0; pitch < 128; ++pitch) {
          ledger.on[pitch] = 0;
          ledger.off[pitch] = 0;
        }
        continue;
      }
      if (roll < 8) {
        r.set_int(0, static_cast<std::int32_t>(rng.range(4)));
        r.set_int(1, static_cast<std::int32_t>(1 + rng.range(12)));
        r.set_bool(2, rng.range(2) == 1);
        r.set_int(3, static_cast<std::int32_t>(rng.range(13)));
        r.set_int(4, static_cast<std::int32_t>(rng.range(5)) - 2);
      }
      Pair ons[4]{};
      std::uint8_t offs[3]{};
      const auto on_count = rng.range(4);
      const auto off_count = rng.range(3);
      for (std::uint32_t k = 0; k < on_count; ++k) ons[k] = {static_cast<std::uint8_t>(48 + rng.range(24)), static_cast<std::uint8_t>(1 + rng.range(127))};
      for (std::uint32_t k = 0; k < off_count; ++k) offs[k] = static_cast<std::uint8_t>(48 + rng.range(24));
      NoteBatch input{}, output{};
      for (std::uint32_t k = 0; k < on_count; ++k) assert(input.on.append({ons[k].pitch, ons[k].velocity, 0}) == PushResult::Added);
      for (std::uint32_t k = 0; k < off_count; ++k) assert(input.off.append({offs[k], 0, 0}) == PushResult::Added);
      TransportView view{};
      ProcessContext context{TimeSample{0, 0}, r.global, view, r.random};
      r.d.process(r.state, context, input, output);
      assert(!output.overflowed());
      ledger.add(output);
      const auto& s = pick_state(r);
      assert(s.active.count <= kPolyphony && s.held.count <= kPolyphony);
      assert(s.count >= 1 && s.count <= 12 && s.output_overflow == 0);
      for (std::uint8_t pitch = 48; pitch < 72; ++pitch) {
        std::int32_t active = 0;
        for (std::uint16_t i = 0; i < s.active.count; ++i) active += s.active.items[i].pitch == pitch ? 1 : 0;
        assert(ledger.sounding(pitch) == active);
      }
    }
    // Drain: releasing every held pitch empties the selection, so nothing is left sounding.
    std::uint8_t held_pitches[kPolyphony]{};
    std::uint16_t held_count = pick_state(r).held.count;
    for (std::uint16_t i = 0; i < held_count; ++i) held_pitches[i] = pick_state(r).held.items[i].pitch;
    NoteBatch input{}, output{};
    for (std::uint16_t i = 0; i < held_count; ++i) assert(input.off.append({held_pitches[i], 0, 0}) == PushResult::Added);
    TransportView view{};
    ProcessContext context{TimeSample{0, 0}, r.global, view, r.random};
    r.d.process(r.state, context, input, output);
    ledger.add(output);
    assert(pick_state(r).held.count == 0 && pick_state(r).active.count == 0);
    for (std::uint8_t pitch = 0; pitch < 128; ++pitch) assert(ledger.sounding(pitch) == 0);
  }
}

void report_sizes() {
  std::printf("t09h latch/pick: sizeof(LatchModuleState)=%zu sizeof(PickModuleState)=%zu sizeof(ModuleState)=%zu (arp=%zu)\n",
              sizeof(LatchModuleState), sizeof(PickModuleState), sizeof(ModuleState), sizeof(ArpModuleState));
}
}  // namespace

int main() {
  test_descriptor();
  test_latch_channel_and_matching();
  test_latch_capacity_and_reset();
  test_pick_reset_and_capacity();
  test_pick_octave_range();
  run_golden_traces();
  test_latch_fuzz_balance();
  test_pick_fuzz_balance();
  report_sizes();
  return 0;
}
